import json
from collections import Counter, defaultdict

# Load schema
with open('data/wikievents/event_role_KAIROS.json') as f:
    schema = json.load(f)

# Build constraint map: (event_type, role) -> set of allowed entity types
constraint_map = {}
for evt_type, info in schema.items():
    roles = info.get('roles', [])
    role_types = info.get('role_types', [])
    for i, role in enumerate(roles):
        if i < len(role_types):
            constraint_map[(evt_type, role)] = set(role_types[i])

# Check data against constraints
total_args = 0
args_with_entity = 0
constraint_satisfied = 0
constraint_violated = 0
constraint_unknown = 0
violations = []

for split in ['train', 'dev', 'test']:
    with open(f'data/wikievents/{split}.jsonl') as f:
        for line in f:
            if not line.strip(): continue
            d = json.loads(line)

            # Build entity_id -> entity_type map
            eid2type = {}
            for ent in d.get('entity_mentions', []):
                eid2type[ent['id']] = ent.get('entity_type', 'UNK')

            for evt in d.get('event_mentions', []):
                evt_type = evt.get('event_type')
                for arg in evt.get('arguments', []):
                    total_args += 1
                    role = arg.get('role')
                    eid = arg.get('entity_id')
                    if eid and eid in eid2type:
                        args_with_entity += 1
                        et = eid2type[eid].lower()
                        key = (evt_type, role)
                        if key in constraint_map:
                            allowed = constraint_map[key]
                            if et in allowed:
                                constraint_satisfied += 1
                            else:
                                constraint_violated += 1
                                if len(violations) < 10:
                                    violations.append(f'{evt_type}.{role}: got {et}, allowed {allowed}')
                        else:
                            constraint_unknown += 1

print(f'Total arguments: {total_args}')
print(f'Arguments with entity type: {args_with_entity}')
print(f'Constraint satisfied: {constraint_satisfied}')
print(f'Constraint violated: {constraint_violated}')
print(f'Constraint key not in schema: {constraint_unknown}')
print(f'Satisfaction rate: {constraint_satisfied/(constraint_satisfied+constraint_violated)*100:.1f}%' if (constraint_satisfied+constraint_violated) > 0 else 'N/A')
print()
if violations:
    print('Sample violations:')
    for v in violations:
        print(f'  {v}')

# Also check: how many distinct (event_type, role, entity_type) triples exist
triples = Counter()
for split in ['train', 'dev', 'test']:
    with open(f'data/wikievents/{split}.jsonl') as f:
        for line in f:
            if not line.strip(): continue
            d = json.loads(line)
            eid2type = {}
            for ent in d.get('entity_mentions', []):
                eid2type[ent['id']] = ent.get('entity_type', 'UNK')
            for evt in d.get('event_mentions', []):
                for arg in evt.get('arguments', []):
                    eid = arg.get('entity_id')
                    if eid and eid in eid2type:
                        triples[(evt['event_type'], arg['role'], eid2type[eid])] += 1

print(f'\nDistinct (event_type, role, entity_type) triples: {len(triples)}')
"
